async function generateToday(date){const targetDate=typeof date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(date)?date:/^\d{4}-\d{2}-\d{2}$/.test(selectedDate)?selectedDate:state.today;const b=app.querySelector('#generate'),status=app.querySelector('#generation-state');if(b){b.disabled=true;b.textContent='正在整理…';}if(status)status.textContent='正在整理這一天的日記，你可以先離開。';try{if(draftText.trim()||files.length)await saveCapture();await api('generate',{date:targetDate});state=await api('state');const d=state.family.diaries.find(d=>d.date===targetDate);if(d)showDiary(d.id);else{activeView=null;render();note('今天還沒有素材，先留一張紙條吧。');}}catch(e){note(e.message);if(status)status.textContent=e.message;if(b){b.disabled=false;b.textContent='重試整理';}}}
function showDiary(id){tab='diary';activeView={kind:'diary',id};saveView();const d=state.family.diaries.find(d=>d.id===id);app.innerHTML=`<button id="back-today">回到今天</button>${diaryView(d)}`;app.querySelector('#back-today').onclick=()=>{tab='today';activeView=null;saveView();render();};bindCommon();scrollTo(0,0);}
function bindNotes(){app.querySelectorAll('[data-open-moment]').forEach(b=>b.onclick=()=>openMoment(b.dataset.openMoment));app.querySelectorAll('[data-receipts]').forEach(b=>b.onclick=()=>{const m=state.family.moments.find(m=>m.id===b.dataset.receipts),name=id=>state.members.find(x=>x.id===id)?.name||'家人';note(`看過：${[...new Set((m.seenBy||[]).filter(r=>r.memberId!==m.authorId).map(r=>name(r.memberId)))].join('、')||'還沒有其他家人'}；播放過：${[...new Set((m.playedBy||[]).filter(r=>r.memberId!==m.authorId).map(r=>name(r.memberId)))].join('、')||'還沒有其他家人'}`);});app.querySelectorAll('[data-note]').forEach(el=>{const m=state.family.moments.find(m=>m.id===el.dataset.note);if(!m)return;let index=0;el.querySelectorAll('audio,video,img').forEach(media=>{const n=Number(media.dataset.mediaIndex??index++);if(media.tagName==='AUDIO'){let seconds=0,last=0,reported=false;media.onplay=()=>{last=performance.now();};media.ontimeupdate=()=>{if(media.paused)return;const now=performance.now();seconds+=Math.min((now-last)/1000,1);last=now;if(seconds>=1&&!reported){reported=true;api('receipt',{id:m.id,kind:'played',mediaIndex:n,playedSeconds:seconds}).catch(()=>{});}};}if(media.tagName==='IMG')media.onclick=()=>{const dialog=document.createElement('dialog');dialog.innerHTML=`<button>關閉照片</button><img src="${esc(media.src)}" alt="生活照片" style="max-width:100%;max-height:80vh">`;document.body.append(dialog);dialog.querySelector('button').onclick=()=>{dialog.close();dialog.remove();};dialog.showModal();};});});}
function restoreView(view){
 if(!view)return render();
 if(view.kind==='sources')showSources(view);
 else if(view.kind==='diary')showDiary(view.id);
 else if(view.kind==='book')bookView(view.id);
 else if(view.kind==='book-preview')previewBook();
 else if(view.kind==='edit')editView(view.id);
 else if(view.kind==='moment')openMoment(view.id);
 else{activeView=null;tab=view.tab||'today';render();scrollTo(0,view.scroll||0);}
}
function showSources(view){
 activeView=view;saveView();app.innerHTML=`<button id="source-back">${view.parent?.kind==='diary'?'回日記':'回故事集'}</button><h1>${esc(view.title||'原始片段')}</h1>${state.family.moments.filter(m=>view.sourceIds.includes(m.id)).map(momentView).join('')}`;
 app.querySelector('#source-back').onclick=()=>restoreView(view.parent);bindNotes();scrollTo(0,view.scroll||0);
}
