function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}
function renderFiles(){const el=app.querySelector('#file-list');if(!el)return;el.innerHTML=files.map((f,i)=>`<div class="preview-file">${mediaView([f])}<span>${f.kind==='audio'?'一段原聲':f.kind==='image'?'一張照片':'一段短片'} · 尚未送出</span><button type="button" data-remove="${i}">移除</button></div>`).join('');el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{files.splice(Number(b.dataset.remove),1);persistCapture();renderFiles();});}
async function record(){
 let stream;const button=app.querySelector('#record');if(recording){recorder.stop();return;}
 if(files.length>=4)return note('先留下目前素材，再繼續錄音。');
 const key=draftKey(),recordingId=uid(),rawOnly=voiceMode==='raw',memberId=state.member.id;
 try{
  stream=await navigator.mediaDevices.getUserMedia({audio:true});
  if(state?.member.id!==memberId||tab!=='today'||draftKey()!==key){stream.getTracks().forEach(t=>t.stop());return;}
  await beginRecording(key,{id:recordingId,mime:'',rawOnly});
  recording=true;button.textContent='停止錄音';const started=Date.now();
  record.timer=setInterval(()=>{const el=app.querySelector('#record-status');if(el)el.textContent=`正在錄音 ${Math.floor((Date.now()-started)/1000)} 秒`;},1000);
  recorder=startRecording({stream,onChunk:(blob,index)=>appendRecording(recordingId,index,blob),onFinish:async({blob,reason,storageError})=>{
   clearInterval(record.timer);const current=app.querySelector('#record');if(current)current.textContent='正在保留錄音…';
   try{
   if(blob.size){files.push({kind:'audio',name:reason==='interrupted'?'中斷後保留的原音':'家人的原音',data:await readFile(blob),rawOnly,recordingId});if(await persistCapture())await clearRecording(key,recordingId);renderFiles();}
   else await clearRecording(key,recordingId);
   const message=reason==='interrupted'?'錄音已中斷，已保留可用片段。請先試聽，可重錄或留下。':reason==='limit'?'錄音已達本次長度，已保留可用片段，請先試聽。':'錄音已停止，可先播放，再留下紙條。';
   const el=app.querySelector('#record-status');if(el)el.textContent=blob.size?message:'錄音已停止，但沒有取得聲音。請重新錄音或加入音檔。';
   if(storageError)note('部分本機暫存未成功，請先留下這段原音再離開。');
   }finally{recording=false;if(current)current.textContent='再錄一段';}
  }});
 }catch{stream?.getTracks().forEach(t=>t.stop());recording=false;clearInterval(record.timer);if(button)button.textContent='開始錄音';note('無法開始錄音。請允許麥克風，或加入已錄好的聲音。');}
}
function interruptRecording(){if(recording)recorder?.stop('interrupted');}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')interruptRecording();});
window.addEventListener('pagehide',interruptRecording);
async function transcribe(e){const audio=files.find(f=>f.kind==='audio');if(!audio)return note('先錄音，或選一段音檔。');const b=e.target;b.disabled=true;try{const r=await api('transcribe',{audio:audio.data});audio.transcript=r.transcript;const input=app.querySelector('#memory');input.value=[input.value,r.transcript].filter(Boolean).join('\n');localStorage.setItem(draftKey(),input.value);note('轉好了，請先核對小名及內容再送出。');}catch(err){note(err.message);}finally{b.disabled=false;}}
function renderDiaries(){app.innerHTML=`<h1>慢慢長大的日子</h1><p class="intro">原話、原聲和你改過的字，都留在這裡。</p><button id="refresh">重新讀取家人的更新</button>${state.family.diaries.length?state.family.diaries.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(d=>diaryView(d)).join(''):'<p>還沒有日記。到「今天」留下片刻，再看看第一篇。</p>'}`;app.querySelector('#refresh').onclick=load;}
function bindCommon(){bindNotes();app.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editView(b.dataset.edit));app.querySelectorAll('[data-sources]').forEach(b=>b.onclick=()=>{const d=state.family.diaries.find(d=>d.id===b.dataset.sources);showSources({kind:'sources',sourceIds:d.current.sourceIds,parent:{kind:'diary',id:d.id},title:'故事從這裡來'});});app.querySelectorAll('[data-adopt]').forEach(b=>b.onclick=async()=>{const d=state.family.diaries.find(d=>d.id===b.dataset.adopt);try{await api('adopt',{id:d.id,baseRevision:d.current.number});await load();}catch(e){note(e.message);}});app.querySelectorAll('[data-task-status]').forEach(b=>b.onclick=async()=>{try{await api('task-status',{id:b.dataset.id,status:b.dataset.taskStatus});await load();}catch(e){note(e.message);}});}
function editView(id){const d=state.family.diaries.find(d=>d.id===id);currentDiary=d;activeView={kind:"edit",id};saveView();const key=`edit:${state.family.id}:${state.member.id}:${id}`,saved=localStorage.getItem(key);let draft=saved?JSON.parse(saved):{...d.current,baseRevision:d.current.number};app.innerHTML=`<button id="cancel">回到日記</button><h1>讓文字像自己家</h1><p class="hint">你的修改會保留，離開後可繼續。</p><form id="edit"><label for="edit-title">標題</label><input id="edit-title" name="title" value="${esc(draft.title)}" maxlength="150" required><label for="edit-body">今天的故事</label><textarea id="edit-body" name="body" rows="12">${esc(draft.body)}</textarea><details><summary>日記裡的照片與原聲</summary>${versionMedia(state.family,{sourceIds:d.current.sourceIds}).map(m=>`<label class="check-row"><input type="checkbox" name="selectedMedia" value="${m.key}" ${!draft.selectedMedia||draft.selectedMedia.includes(m.key)?'checked':''}><span>${esc(m.author)}留下的${{image:'照片',audio:'原聲',video:'短片'}[m.kind]}</span></label>`).join('')||'<p>這一天沒有媒體。</p>'}</details><p id="edit-error" role="alert" class="error"></p><div class="actions"><button class="primary" type="submit">確認保存</button><button type="button" id="discard">放棄本機草稿</button></div></form><details><summary>先前版本（可還原為新的修改）</summary>${d.versions.slice().reverse().map(v=>`<div class="comment"><small>版本 ${v.number} · ${v.kind==='manual'?'家人修改':'整理草稿'}</small><p>${esc(v.title)}</p><button data-restore="${v.number}">取回這份文字</button></div>`).join('')}</details>`;
const form=app.querySelector('#edit');form.oninput=()=>localStorage.setItem(key,JSON.stringify({title:form.elements.title.value,body:form.elements.body.value,baseRevision:draft.baseRevision,selectedMedia:[...form.querySelectorAll('[name=selectedMedia]:checked')].map(x=>x.value)}));app.querySelector('#cancel').onclick=()=>{activeView=null;saveView();render();};app.querySelector('#discard').onclick=async()=>{try{state=await api('state');localStorage.removeItem(key);activeView=null;saveView();render();}catch(e){note(e.message);}};app.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{const v=d.versions.find(v=>v.number===Number(b.dataset.restore));form.elements.title.value=v.title;form.elements.body.value=v.body;form.oninput();note('文字已取回，確認保存才會成為新版本。');});form.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await api('edit',{id,baseRevision:draft.baseRevision,title:form.elements.title.value,body:form.elements.body.value,selectedMedia:[...form.querySelectorAll('[name=selectedMedia]:checked')].map(x=>x.value)});localStorage.removeItem(key);activeView=null;saveView();note('已保存，你的文字不會被自動整理蓋掉。');await load();}catch(err){app.querySelector('#edit-error').textContent=err.message;if(err.status===409){const latest=await api('state'),fresh=latest.family.diaries.find(x=>x.id===id);const panel=document.createElement('section');panel.className='comment';const heading=document.createElement('h2');heading.textContent='家人剛保存的版本';const content=document.createElement('p');content.style.whiteSpace='pre-wrap';content.textContent=fresh.current.title+'\n'+fresh.current.body;const button=document.createElement('button');button.type='button';button.textContent='我已比較，保留我的文字作新版本';button.onclick=()=>{draft.baseRevision=fresh.current.number;state=latest;form.oninput();panel.remove();app.querySelector('#edit-error').textContent='已保留你的草稿。可先合併家人的內容，再按確認保存；兩個版本都會留下。';};panel.append(heading,content,button);app.querySelector('#edit-error').after(panel);}e.submitter.disabled=false;}};}
async function loadSharedBook(){
 nav.hidden=true;document.querySelector('#logout').hidden=true;
 try{const data=await api('shared-book',{token:sharedReadToken});app.innerHTML=`<p class="date-title">家人分享的故事集</p>${bookContent(data.collection,{public:true,child:data.child,cover:data.media[data.collection.cover],mediaFor:ch=>(ch.mediaKeys||[]).map(key=>data.media[key]).filter(Boolean)})}<p class="hint">只包含分享者選定的內容。這份連結有有效期限。</p>`;}
 catch(e){app.innerHTML=`<h1>這份分享目前無法開啟</h1><p>${esc(e.message)}</p><a href="/">回到小日子</a>`;}
}
const bookDraftKey=()=>`book-draft:${state.family.id}:${state.member.id}`;
function getBookDraft(){try{return JSON.parse(localStorage.getItem(bookDraftKey()))||{title:`${state.family.child}的小日子`,diaryIds:[],template:'journal',cover:'',requestId:uid()};}catch{return {title:`${state.family.child}的小日子`,diaryIds:[],template:'journal',cover:'',requestId:uid()};}}
function renderBooks(){
 const f=state.family,draft=getBookDraft();draft.diaryIds=draft.diaryIds.filter(id=>f.diaries.some(d=>d.id===id));
 const photos=draft.diaryIds.flatMap(id=>versionMedia(f,f.diaries.find(d=>d.id===id).current)).filter(m=>m.kind==='image');
 if(draft.cover&&!photos.some(m=>m.key===draft.cover))draft.cover='';
 app.innerHTML=`<h1>把日子收成一本書</h1><p class="intro">兩天，也能是一本值得留下的小故事。</p><form id="book"><label for="book-title">這本書的名字</label><input id="book-title" name="title" value="${esc(draft.title)}" maxlength="100" required><h2>選入日記</h2>${f.diaries.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(d=>`<label class="check-row"><input type="checkbox" name="diaries" value="${d.id}" ${draft.diaryIds.includes(d.id)?'checked':''}><span>${esc(d.date)} · ${esc(d.current.title)}</span></label>`).join('')||'<p>先留下一篇日記，就能開始第一本。</p>'}<h2>章節順序</h2><ol class="chapter-order">${draft.diaryIds.map((id,i)=>{const d=f.diaries.find(d=>d.id===id);return `<li><span>${esc(d.date)} · ${esc(d.current.title)}</span><button type="button" data-move="${i}" data-direction="-1" ${i===0?'disabled':''}>往前</button><button type="button" data-move="${i}" data-direction="1" ${i===draft.diaryIds.length-1?'disabled':''}>往後</button></li>`;}).join('')}</ol><label for="book-template">版型</label><select id="book-template" name="template">${BOOK_TEMPLATES.map(t=>`<option value="${t.id}" ${draft.template===t.id?'selected':''}>${t.name}</option>`).join('')}</select><label for="book-cover">封面照片</label><select id="book-cover" name="cover"><option value="">純文字封面</option>${photos.map((m,i)=>`<option value="${m.key}" ${draft.cover===m.key?'selected':''}>${esc(m.author)}的照片 ${i+1}</option>`).join('')}</select><p class="hint">保存後保留這次採用的文字、選圖與順序。</p><button type="submit" class="primary" ${draft.diaryIds.length?'':'disabled'}>預覽這本故事集</button></form><h2>我們的故事集</h2>${f.collections.slice().reverse().map(c=>`<article class="feed-item"><h3>${esc(c.title)}</h3><p>${c.chapters.length} 篇日記</p><button data-book="${c.id}">打開這本書</button></article>`).join('')||'<p>第一本書，從今天開始。</p>'}`;
 const form=app.querySelector('#book'),persist=()=>{draft.title=form.elements.title.value;draft.template=form.elements.template.value;draft.cover=form.elements.cover.value;localStorage.setItem(bookDraftKey(),JSON.stringify(draft));};
 form.oninput=persist;app.querySelectorAll('[name=diaries]').forEach(c=>c.onchange=()=>{persist();draft.diaryIds=draft.diaryIds.filter(id=>id!==c.value);if(c.checked)draft.diaryIds.push(c.value);localStorage.setItem(bookDraftKey(),JSON.stringify(draft));const y=scrollY;renderBooks();scrollTo(0,y);});
 app.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{persist();const i=+b.dataset.move,j=i+(+b.dataset.direction);[draft.diaryIds[i],draft.diaryIds[j]]=[draft.diaryIds[j],draft.diaryIds[i]];localStorage.setItem(bookDraftKey(),JSON.stringify(draft));renderBooks();});
 form.onsubmit=e=>{e.preventDefault();persist();previewBook();};app.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>bookView(b.dataset.book));
}
function bookContent(c,context){
 const f=state?.family||{child:context?.child,moments:[]},mediaFor=context?.mediaFor||(ch=>versionMedia(f,ch)),child=context?.child||f.child;
 const cover=context?.cover||(c.cover?c.chapters.flatMap(mediaFor).find(m=>m.key===c.cover):null);
 return `<div class="book-layout template-${c.template==='album'?'album':'journal'}"><section class="book-cover">${cover?`<img class="cover-photo" src="${esc(cover.data)}" alt="故事集封面照片">`:''}<h1>${esc(c.title)}</h1><p>${esc(child)} · ${c.chapters.length} 個值得留下的日子</p></section>${c.chapters.map((ch,i)=>`<article class="diary"><p class="date-title">${esc(ch.date)}</p><h2>${esc(ch.title)}</h2><p class="story-text">${esc(ch.body)}</p>${mediaView(mediaFor(ch),'story-media')}${context?.public?'':`<button data-chapter-source="${i}">看這一章的原素材</button>`}</article>`).join('')}</div>`;
}
function bindChapterSources(c){app.querySelectorAll('[data-chapter-source]').forEach(b=>b.onclick=()=>{const ch=c.chapters[+b.dataset.chapterSource];showSources({kind:'sources',sourceIds:ch.sourceIds,title:'這一章的原素材',parent:c.id?{kind:'book',id:c.id}:{kind:'book-preview'}});});}
function previewBook(){
 let c;try{c=bookSnapshot(state.family,getBookDraft());}catch(e){note(e.message);return renderBooks();}
 activeView={kind:'book-preview'};saveView();app.innerHTML=`<div class="actions"><button id="back-arrange">回編排</button><button id="save-book" class="primary">確認保存這本書</button></div><p class="hint">這是保存前預覽，尚未保存到家庭。</p><p id="book-error" class="error" role="alert"></p><button id="refresh-preview" hidden>讀取家人更新，再預覽</button>${bookContent(c)}`;
 app.querySelector('#back-arrange').onclick=()=>{activeView=null;saveView();renderBooks();};app.querySelector('#refresh-preview').onclick=async()=>{state=await api('state');previewBook();};bindChapterSources(c);
 app.querySelector('#save-book').onclick=async e=>{e.target.disabled=true;e.target.textContent='正在保存…';const draft=getBookDraft(),expectedRevisions=Object.fromEntries(c.chapters.map(ch=>[ch.diaryId,ch.number])),shape=JSON.stringify({title:draft.title,diaryIds:draft.diaryIds,template:draft.template,cover:draft.cover,expectedRevisions});if(draft.requestShape!==shape){draft.requestId=uid();draft.requestShape=shape;localStorage.setItem(bookDraftKey(),JSON.stringify(draft));}try{const r=await api('collection',{...draft,expectedRevisions});localStorage.removeItem(bookDraftKey());state=await api('state');activeView=null;bookView(r.collection.id);note('故事集已保存，之後可再打開。');}catch(err){app.querySelector('#book-error').textContent=err.message;if(err.status===409)app.querySelector('#refresh-preview').hidden=false;e.target.disabled=false;e.target.textContent='重試保存';}};
}
function bookView(id){
 activeView={kind:'book',id};saveView();const c=state.family.collections.find(c=>c.id===id);app.innerHTML=`<div class="actions no-print"><button id="back-books">回故事集</button><button id="print">列印／存成 PDF</button><button id="share-book">分享這本故事集</button></div>${bookContent(c)}<p class="hint">線上可聽原聲及看短片；PDF包含文字與照片。</p><section id="book-share-panel"></section>`;
 app.querySelector('#back-books').onclick=()=>{activeView=null;saveView();renderBooks();};app.querySelector('#print').onclick=()=>window.print();bindChapterSources(c);
 app.querySelector('#share-book').onclick=()=>{const panel=app.querySelector('#book-share-panel');panel.innerHTML=`<h2>分享範圍</h2><p>只分享「${esc(c.title)}」的這份文字、所選照片、原聲與短片，不包含其他便條、家庭留言或成員資料。持有連結的人可閱讀，7天內有效；可隨時收回。</p><button id="confirm-book-share" class="primary">建立這本書的分享連結</button><p id="book-share-result" role="status"></p>`;panel.querySelector('button').onclick=async e=>{e.target.disabled=true;try{const r=await api('book-share',{id:c.id});const url=location.origin+'/#read='+r.token;panel.querySelector('#book-share-result').innerHTML=`<label>故事集分享連結<input readonly value="${esc(url)}"></label><button id="copy-book-share">複製連結</button><button id="revoke-book-share">收回這份分享</button>`;panel.querySelector('#copy-book-share').onclick=async()=>{try{await navigator.clipboard.writeText(url);note('故事集連結已複製。');}catch{panel.querySelector('input').select();note('請複製選取的連結。');}};panel.querySelector('#revoke-book-share').onclick=async()=>{await api('book-share-revoke',{id:r.id});panel.querySelector('#book-share-result').textContent='這份分享已收回。';};}catch(err){panel.querySelector('#book-share-result').textContent=err.message;e.target.disabled=false;}};};
}
function taskView(t){const status={unread:'未讀',read:'已讀',accepted:'已接手',done:'已完成'}[t.status];const due=new Date(t.dueAt);return `<article class="task"><strong>${esc(t.text)}</strong><p class="byline">${esc(state.members.find(m=>m.id===t.assigneeId)?.name||'家人')} · ${esc(due.toLocaleString('zh-TW',{timeZone:state.family.timezone}))} · ${status} · 僅在 App 內提醒${due<Date.now()&&t.status!=='done'?' · 時間到了':''}</p>${t.assigneeId===state.member.id&&t.status!=='done'?`<div class="actions">${t.status==='unread'?`<button data-id="${t.id}" data-task-status="read">我看到了</button>`:''}${t.status!=='accepted'?`<button data-id="${t.id}" data-task-status="accepted">我來接手</button>`:''}<button data-id="${t.id}" data-task-status="done">已完成</button></div>`:''}</article>`;}
function renderFamily(){const f=state.family;app.innerHTML=`<h1>一起照顧，一起記得</h1><p class="intro">${esc(f.name)} · ${state.members.map(m=>esc(m.name)).join('、')}</p><button id="refresh-family">讀取家人最新消息</button><h2>家裡的話</h2>${f.comments.slice().reverse().map(c=>`<article class="comment"><p class="byline">${esc(c.author)} · ${c.readBy.includes(state.member.id)?'你已讀':'你未讀'}</p><p>${esc(c.text)}</p><small>${c.recipientId?'私人留言・僅作者與'+esc(state.members.find(m=>m.id===c.recipientId)?.name||'收件人')+'可見':'全家可見'} · ${c.readBy.length} 人已讀，不代表已完成</small></article>`).join('')||'<p>留一句話給家人。</p>'}<button id="mark-read">標為我已讀</button><form id="comment"><label for="comment-recipient">誰可以看</label><select id="comment-recipient" name="recipientId"><option value="">全家可見</option>${state.members.filter(m=>m.id!==state.member.id).map(m=>`<option value="${m.id}">只給${esc(m.name)}・私人留言</option>`).join('')}</select><p class="hint">私人留言不會進入全家日記。</p><label for="comment-text">給家人的話</label><textarea id="comment-text" name="text" rows="2" required></textarea><button type="submit">留下留言</button></form><h2>交給家人的事</h2>${f.tasks.map(taskView).join('')||'<p>目前沒有交接事項。</p>'}<form id="task"><label for="task-text">提醒什麼事</label><input id="task-text" name="text" required><div class="two-col"><div><label for="assignee">交給誰</label><select id="assignee" name="assigneeId">${state.members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div><div><label for="due">家庭時間</label><input id="due" name="due" type="datetime-local" required></div></div><button type="submit">交給家人</button><p class="hint">僅在 App 內提醒；離開頁面不會響鈴或推播。時間依家庭時區設定。</p></form>${state.member.role==='owner'?`<h2>邀請家人一起</h2><p class="hint">建立一次性邀請碼，交給信任的家人。7天內有效；對方選「加入家人」建立自己的帳號。</p><button id="invite">建立邀請碼</button><p id="invite-result"></p><h2>晚上的故事時間</h2><form id="settings"><label for="evening">每天整理時間</label><input id="evening" type="time" name="evening" step="900" value="${f.evening}" required><label for="timezone">家庭時區</label><select id="timezone" name="timezone">${['Asia/Taipei','Asia/Hong_Kong','Asia/Tokyo','Europe/London','America/Los_Angeles','America/New_York'].map(z=>`<option ${z===f.timezone?'selected':''}>${z}</option>`).join('')}</select><button type="submit">保存故事時間</button><p class="hint">手機關掉仍會整理。有新素材才更新，人工文字另提候選。更改時區不改已排定提醒的實際時刻，只改時間顯示。</p></form>`:''}<details><summary>回收區（可復原）</summary>${f.moments.filter(m=>m.archivedAt&&(m.authorId===state.member.id||state.member.role==='owner')).map(m=>`<p>${esc(momentTitle(m))}<button data-restore-note="${m.id}">復原紙條</button></p>`).join('')||'<p>目前沒有移入回收區的紙條。</p>'}</details><details><summary>把小日子放到手機主畫面</summary><p>iPhone：用 Safari 打開，按分享，再選「加入主畫面」。Android：用 Chrome 的選單選「加入主畫面」或「安裝應用程式」。</p><p class="hint">下次點圖示可回來繼續；登入與草稿保存在這個瀏覽器。這不會開啟系統推播，提醒仍只在頁內顯示。</p></details><h2>試用與自己的記錄</h2><p>30天試用至 ${esc(f.trialEndsAt.slice(0,10))}。目前不收費。</p><p class="hint">399元／月、五位成員為討論起點，尚非販售方案。測試每檔8MB、每次4檔、家庭20MB（含編碼）；每日最多30次AI整理、20次轉寫，手動修改不限次。不按故事數收費。到期後此版仍可閱讀及匯出，正式保存政策待定。</p><button id="export">下載家庭原始資料</button>`;
app.querySelectorAll('[data-restore-note]').forEach(b=>b.onclick=async()=>{await api('moment-archive',{id:b.dataset.restoreNote,restore:true});await load();});app.querySelector('#refresh-family').onclick=load;app.querySelector('#mark-read').onclick=async()=>{await api('read',{});await load();};for(const name of ['comment','task','settings']){const form=app.querySelector('#'+name);if(form)form.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(form));b.requestId=form.dataset.requestId||(form.dataset.requestId=uid());if(name==='task')b.dueAt=familyInstant(b.due,state.family.timezone);await api(name,b);await load();note('已保存。');}catch(err){note(err.message);e.submitter.disabled=false;}};}const inv=app.querySelector('#invite');if(inv)inv.onclick=async()=>{try{const r=await api('invite',{});const link=location.origin+'/#join='+encodeURIComponent(r.code);app.querySelector('#invite-result').innerHTML=`<label for="family-invite-link">家庭邀請連結</label><input id="family-invite-link" readonly value="${esc(link)}"><button id="copy-invite-link" type="button">複製家庭邀請連結</button><small>這份連結可加入私人家庭，僅交給信任的家人。一次使用，7天內有效。</small><details><summary>手動輸入邀請碼</summary><code>${esc(r.code)}</code></details>`;app.querySelector('#copy-invite-link').onclick=async()=>{try{await navigator.clipboard.writeText(link);note('家庭邀請連結已複製，可貼到 WhatsApp 給信任的家人。');}catch{app.querySelector('#family-invite-link').select();note('請複製已選取的家庭邀請連結。');}};}catch(e){note(e.message);}};app.querySelector('#export').onclick=async()=>{try{const result=await api('export');const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='little-days-family.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){note(e.message);}};}
nav.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(captureTransfer)return note('正在保存，請稍候或取消這次傳送。');if(recording)return note('請先停止錄音，再切換頁面。');persistCapture();activeView=null;tab=b.dataset.tab;saveView();render();window.scrollTo(0,0);});document.querySelector('#logout').onclick=async()=>{if(recording)return note('請先停止錄音。');await api('logout',{});files=[];draftText='';captureId=uid();restoredKey='';await load();};window.addEventListener('beforeunload',e=>{if(files.length||recording){e.preventDefault();e.returnValue='';}});load();
